export function restoreLaterForearmEpoch(bytes){
 const witness=readFileSync(new URL('./fixtures/forearm-later-current-epoch-seams.json',import.meta.url));
 assert.equal(sha(witness),'5174d574b3dcb0299bedaa8d4ce398347fc43ab3dee3fa2a9482cbf094cd7258',
  'Exact independently witnessed later forearm seams');
 const proof=JSON.parse(witness);
 assert.equal(proof.schema,'vm-forearm-later-current-epoch-seams/1');
 assert.equal(proof.currentSha256,'b6df69f8035211bf2ee253fa2d216cb598259e771917eefa44a468506cbcf85f');
 assert.equal(proof.historicalSha256,'90b1c26a19220053633a277b10d94b74c4d3c2f6ebc6e3cd8ccf4bccdd2fdda4');
 assert.equal(sha(bytes),proof.currentSha256,'Exact later forearm source bytes');
 const text=bytes.toString('utf8');
 assert.deepEqual(Buffer.from(text),bytes,'Lossless later forearm UTF-8 source');
 const lines=text.match(/[^\n]*\n|[^\n]+$/g)||[];
 assert.equal(lines.length,proof.currentLines);
 assert.equal(proof.seams.length,6,'Only six declared later forearm hunks');
 for(const seam of [...proof.seams].reverse()){
  assert.deepEqual(lines.slice(seam.afterStart,seam.afterStart+seam.after.length),seam.after,
